const body = $json.body || $json;
const data = body.data || body;
const message = data.message || data.messages?.[0] || data;
const key = message.key || data.key || {};
const fromMe = Boolean(key.fromMe || message.fromMe || data.fromMe || body.fromMe || body.sent);
const remoteJid = key.remoteJid || message.remoteJid || data.remoteJid || data.from || body.from || '';
const text = message.message?.conversation || message.message?.extendedTextMessage?.text || data.text || body.text || '';
const normalized = String(text).trim().toLowerCase();
let intent = 'fallback';
let reply = 'Recebi sua mensagem. Um atendente do Mercado do Vale vai continuar por aqui.';
if (fromMe) {
  intent = 'human_outbound';
  reply = '';
} else if (/^(oi|ola|olá|bom dia|boa tarde|boa noite)\b/.test(normalized)) {
  intent = 'saudacao';
  reply = 'Oi! Sou o assistente de teste do Mercado do Vale. Posso ajudar com produto, horario, entrega ou chamar um atendente.';
} else if (/(iphone|celular|produto|preco|preço|valor|tem )/.test(normalized)) {
  intent = 'produto_preco';
  reply = 'Me diga o modelo ou produto que voce procura que eu verifico as opcoes para atendimento.';
} else if (/(horario|horário|endereco|endereço|abre|fecha|localizacao|localização)/.test(normalized)) {
  intent = 'horario_endereco';
  reply = 'Nosso atendimento pode confirmar horario e endereco atualizados. Vou encaminhar sua mensagem para conferencia.';
} else if (/(entrega|frete|delivery|motoboy|enviar)/.test(normalized)) {
  intent = 'entrega';
  reply = 'Fazemos atendimento para entrega conforme disponibilidade e endereco. Me envie seu bairro para verificar.';
} else if (/(atendente|humano|pessoa|vendedor|falar com alguem|falar com alguém)/.test(normalized)) {
  intent = 'falar_atendente';
  reply = 'Certo, vou deixar sua conversa marcada para atendimento humano.';
}
return [{ json: { fromMe, remoteJid, text, normalized, intent, reply, shouldReply: !fromMe && Boolean(reply) } }];
